for(const side of [0,1]){const x=side?402:0;rect(x,108,30,660,'#2a3c38');for(let i=0;i<8;i++){const y=110+i*95+(t*18)%95;rect(x+2,y,27,68,'#687565');rect(x+4,y+4,23,3,'#98a08a');rect(x+7,y+18,15,30,'#283c39');rect(x+9,y+21,5,10,i%3?'#576c5d':'#c9b271');rect(x+18,y+21,2,26,'#8c9480');rect(x+5,y+55,20,6,'#41544a')}}
