function supportTimeScale(){return ['easy','normal'].includes(run?.difficulty)&&(aim||command) ? .25 : 1;}
function frame(now){const raw=Math.min(.05,(now-last)/1000||0);last=now;visualTime+=raw;mixer.update(raw,run?.state==='playing'?(run.bossSpawned&&!run.bossKilled?'boss':'patrol'):run?.state==='paused'||run?.state==='inventory'?'paused':run?(run.state==='cleared'||run.state==='won'?'victory':run.state==='lost'?'defeat':'ended'):'menu',{orbital:run?.effects.some(e=>e.type==='laser'&&e.age>=(e.arrival||0)&&e.age<e.duration),squad:run?.effects.some(e=>e.type==='squadBeam'&&e.age<e.duration)});if(run?.state==='playing'&&visualTime-lastGroan>5){const infected=run.entities.filter(o=>F.TYPES[o.type]&&o.y>145&&o.y<580).sort((a,b)=>(b.type==='giant'?1000:b.y)-(a.type==='giant'?1000:a.y))[0];if(infected){mixer.creature(infected.type);lastGroan=visualTime;}}const running=run?.state==='playing',dt=raw*supportTimeScale();if(running){{let delta=0;if(keys.has('a')||keys.has('arrowleft'))delta-=650*dt;if(keys.has('d')||keys.has('arrowright'))delta+=650*dt;if(delta)run.move(run.targetX+delta);}const previousPositions=new Map(run.entities.map(o=>[o,{x:o.x,y:o.y}]));let remain=dt;while(remain>0&&run.state==='playing'){const step=Math.min(.016,remain);run.step(step);remain-=step;}for(const o of run.entities){const before=previousPositions.get(o);locomotion.set(o,!!before&&o.y-before.y>.02);}events();hud();for(const c of corpses){c.age+=dt;c.y+=run.roadSpeed()*dt;}corpses=corpses.filter(c=>c.age<c.life);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=70*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);for(const f of floaters){f.y-=22*dt;f.life-=dt;}floaters=floaters.filter(f=>f.life>0);for(const r of ripples)r.age+=dt;ripples=ripples.filter(r=>r.age<.6);shake=Math.max(0,shake-dt*24);flash=Math.max(0,flash-dt);if(toastLife>0){toastLife-=dt;if(toastLife<=0)$('#toast').style.opacity=0;}}updatePrologue();updateFieldComms();updateEnemyComms();signalUpdate();if($('#overlay').dataset.view!==overlayState)$('#overlay').dataset.view=overlayState;render();if(overlayState==='gallery')drawGallery();requestAnimationFrame(frame);}
function focusLost(){keys.clear();movePointer=null;clearAim();if(run?.state==='playing')pause();}window.addEventListener('blur',focusLost);document.addEventListener('visibilitychange',()=>{if(document.hidden)focusLost();});$('#pause').onclick=pause;$('#sound').onclick=()=>{soundOn=mixer.toggle();$('#sound').classList.toggle('muted',!soundOn);$('#sound').setAttribute('aria-label',soundOn?'关闭声音':'开启声音');if(soundOn)sound('loot');};
