window.emberAndroid={pause:()=>{focusLost();mixer.stopSpeech();mixer.stopLaser();for(const a of Object.values(mixer.tracks))a.pause();},back:()=>{if($('#signalConsole')){$('#signalConsole').remove();return 'handled';}if(command||aim){cancelSupport();return 'handled';}if(prologue?.phase==='dialog'){$('#skipStory')?.click();return 'handled';}if(run?.state==='playing'){pause();return 'handled';}if(overlayState==='paused')return 'exit';if(overlayState==='briefing'){briefingBack();return 'handled';}if(overlayState!=='menu'&&!['cleared','lost','won'].includes(overlayState)){menu();return 'handled';}return 'exit';}};
